{id:'bug-report',track:'Manual QA',level:'Foundation',frameworks:['Manual'],title:'Bug Hunt · Report the discount defect',description:'Reproduce the seeded cart defect and submit a concise, actionable report.',lab:'bughunt',target:'Bug Hunt Arcade',scenario:'SAVE10 discounts the shipping fee, even though the promotion applies only to merchandise.',hint:'Include exact prices, the promotion rule, and the difference between expected and actual totals.'}
