let activeChallenge=challengeData[0];
function renderChallenges(){const track=document.getElementById('challengeTrack').value,level=document.getElementById('challengeLevel').value,framework=document.getElementById('challengeFramework').value;const list=challengeData.filter(c=>(track==='all'||c.track===track)&&(level==='all'||c.level===level)&&(framework==='all'||c.frameworks.includes(framework)));document.getElementById('challengeLibrary').innerHTML=list.map(c=>`<article class="challenge-card" data-track="${escapeHtml(c.track)}"><div class="challenge-meta"><span class="tile tile-sm ch-tile">${icon({'Manual QA':'list-checks','API testing':'plug','Web automation':'rocket','Mobile testing':'phone'}[c.track]||'trophy')}</span><span class="badge badge-brand">${escapeHtml(c.track)}</span><span class="badge ch-level">${escapeHtml(c.level)}</span>${(state.submissions||[]).some(x=>x.challengeId===c.id)?`<span class="badge badge-success">${icon('check')}Submitted</span>`:''}</div><h3>${escapeHtml(c.title)}</h3><p>${escapeHtml(c.description)}</p><div class="challenge-tags">${c.frameworks.map(f=>`<span>${escapeHtml(f)}</span>`).join('')}<span>${icon('cursor','ic-xs')}Built-in app</span></div><button class="btn btn-primary btn-sm" type="button" data-challenge="${c.id}">Start challenge${icon('arrow-right','flip-rtl')}</button></article>`).join('')||`<div class="empty card"><span class="tile">${icon('filter')}</span><h3>No challenges match</h3><p>Try another track, level or framework.</p></div>`;document.querySelectorAll('[data-challenge]').forEach(b=>b.addEventListener('click',()=>beginChallenge(b.dataset.challenge)))}
function defaultScript(framework){if(framework==='Manual')return `Test plan · PeopleOps Portal\n\n1. Valid login: ...\n2. Invalid credentials: ...\n3. Logout and protected route: ...\n\nRisk and test data notes: ...`;if(framework==='Postman')return `// Postman-style API checks\npm.test('returns an employee profile', () => {\n  pm.response.to.have.status(200);\n  const body = pm.response.json();\n  pm.expect(body).to.have.property('id');\n  // TODO: add schema and negative checks\n});`;if(framework.startsWith('Cypress'))return `describe('PeopleOps Portal sign-in', () => {\n  it('rejects invalid credentials', () => {\n    cy.visit('/practice/peopleops');\n    // TODO: submit invalid credentials\n    // TODO: assert the visible error message\n  });\n});`;if(framework.startsWith('Selenium'))return `from selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\n\ndef test_peopleops_login(driver):\n    driver.get('/practice/peopleops')\n    # TODO: enter demo credentials\n    # TODO: assert the employee dashboard is visible\n`;return `import { test, expect } from '@playwright/test';\n\ntest('employee can sign in and sign out', async ({ page }) => {\n  await page.goto('/practice/peopleops');\n  // TODO: use a stable, user-facing locator\n  // TODO: assert the signed-in dashboard\n});`}
function renderTargetApp(){const root=document.getElementById('targetAppView');if(!root)return;const target=activeChallenge.target;document.getElementById('targetTitle').textContent=target;document.getElementById('targetScenario').textContent=activeChallenge.scenario;let content='';if(activeChallenge.lab==='login')content=`<div class="target-logo">P</div><b>PeopleOps Portal</b><span>Practice employee services</span><label>Username<input id="practiceTargetUsername" value="qa.learner@peopleops.local" autocomplete="off"></label><label>Password<input id="practiceTargetPassword" value="LabPass123" type="password" autocomplete="off"></label><button class="btn btn-primary btn-sm" type="button" data-target-action="peopleops-login">Sign in to simulation</button><div id="targetAppResult" class="target-result">Use the fictional demo account to explore this simulated flow.</div>`;else if(activeChallenge.lab==='api')content=`<div class="target-logo">API</div><b>API Sandbox request</b><span>Controlled mock response · no network request</span><label>Method<select id="embeddedMethod"><option>GET</option><option>POST</option></select></label><label>Endpoint<input id="embeddedEndpoint" value="/api/employees/104"></label><button class="btn btn-primary btn-sm" type="button" data-target-action="api-run">Send simulated request</button><pre id="targetAppResult" class="target-result">No request sent yet.</pre>`;else if(activeChallenge.lab==='checkout'||activeChallenge.lab==='bughunt')content=`<div class="target-logo">S</div><b>ShopFlow Store</b><span>Merchandise $48.00 · Shipping $6.00</span><label>Promotion<select id="embeddedCoupon"><option>SAVE10</option><option>No coupon</option></select></label><button class="btn btn-primary btn-sm" type="button" data-target-action="cart-run">Recalculate simulated cart</button><div id="targetAppResult" class="target-result">Seeded behavior: coupon is incorrectly applied to shipping.</div>`;else if(activeChallenge.lab==='ui')content=`<div class="target-logo">UI</div><b>UI Components Playground</b><span>Dynamic form and table sample</span><label>Filter employees<input id="embeddedFilter" placeholder="Search name or team"></label><button class="btn btn-primary btn-sm" type="button" data-target-action="ui-run">Apply filter</button><div id="targetAppResult" class="target-result">Rows: Alex Carter · Sam Rivera · Jordan Lee</div>`;else content=`<div class="target-logo">M</div><b>Mobile Experience Lab</b><span>Device state simulator</span><label><input id="embeddedOffline" type="checkbox"> Simulate offline network</label><button class="btn btn-primary btn-sm" type="button" data-target-action="mobile-run">Resume upload</button><div id="targetAppResult" class="target-result">Upload progress saved at 68%.</div>`;root.innerHTML=content}
function beginChallenge(id,opts){activeChallenge=challengeData.find(c=>c.id===id)||challengeData[0];const draft=state.workspaceDrafts[activeChallenge.id]||{};document.getElementById('workspaceTitle').textContent=activeChallenge.title;document.getElementById('workspaceDescription').textContent=activeChallenge.description;document.getElementById('frameworkSelect').value=draft.framework||`${activeChallenge.frameworks[0]}${activeChallenge.frameworks[0]==='Playwright'?' · TypeScript':activeChallenge.frameworks[0]==='Cypress'?' · JavaScript':activeChallenge.frameworks[0]==='Selenium'?' · Python':''}`;document.getElementById('scriptEditor').value=draft.code||defaultScript(document.getElementById('frameworkSelect').value);document.getElementById('approachEditor').value=draft.approach||'';document.getElementById('testCasesEditor').value=draft.testCases||'';document.getElementById('workspaceHintText').hidden=true;document.getElementById('workspaceModel').hidden=true;document.getElementById('submitFeedback').hidden=true;document.getElementById('draftState').textContent=draft.updatedAt?`Draft saved ${new Date(draft.updatedAt).toLocaleString()}`:'New draft';renderTargetApp();if(!(opts&&opts.silent))showScreen('workspace')}
function saveWorkspaceDraft(showToast=false){const draft={challengeId:activeChallenge.id,framework:document.getElementById('frameworkSelect').value,code:document.getElementById('scriptEditor').value,approach:document.getElementById('approachEditor').value,testCases:document.getElementById('testCasesEditor').value,updatedAt:new Date().toISOString()};state.workspaceDrafts[activeChallenge.id]=draft;try{localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('draftState').textContent='Saved in this browser';if(showToast)toast('Draft saved on this device.')}catch{toast('Browser storage is full. Export your submissions to keep a copy.')}}
function submitWorkspace(){saveWorkspaceDraft();const code=document.getElementById('scriptEditor').value,approach=document.getElementById('approachEditor').value,testCases=document.getElementById('testCasesEditor').value,framework=document.getElementById('frameworkSelect').value;const coverage=(/test\s*\(|it\s*\(|pm\.test|test case/i.test(code+testCases)?22:10)+(testCases.length>100?8:0);const assertions=/expect\(|assert|should\(|to\.have|to\.be/.test(code)?25:7;const reliable=/(getByRole|getByLabel|data-testid|find_element|WebDriverWait|waitFor)/.test(code)&&!/(waitForTimeout|sleep\s*\()/.test(code)?25:12;const reasoning=approach.length>140?20:approach.length>45?13:4;const rubric={coverage:Math.min(30,coverage),assertions,reliability:reliable,approach:reasoning},score=Object.values(rubric).reduce((a,b)=>a+b,0);const record={id:'sub-'+Date.now(),challengeId:activeChallenge.id,title:activeChallenge.title,framework,code,approach,testCases,rubric,score,createdAt:new Date().toISOString(),executed:false};state.submissions.unshift(record);state.submissions=state.submissions.slice(0,100);state.lastSubmissionId=record.id;state.challengeWeak=state.challengeWeak||[];if(score<70&&!state.challengeWeak.includes(activeChallenge.id))state.challengeWeak.push(activeChallenge.id);if(score>=70)state.challengeWeak=state.challengeWeak.filter(id=>id!==activeChallenge.id);state.days=state.days||[];if(!state.days.includes(today()))state.days.push(today());save();const panel=document.getElementById('submitFeedback');panel.hidden=false;panel.className=`submit-feedback ${score>=70?'good':'mid'}`;panel.innerHTML=`<div class="sf-top"><span class="score-pill ${score>=70?'good':score>=50?'mid':'low'}">${score}/100</span><b>Saved submission</b></div><div class="sf-bars">${[['Coverage',rubric.coverage,30],['Assertions',rubric.assertions,25],['Reliability',rubric.reliability,25],['Approach',rubric.approach,20]].map(([n,v,m])=>`<div><span>${n}</span><span class="tnum">${v}/${m}</span><div class="bar bar-sm"><i style="width:${Math.round(v/m*100)}%"></i></div></div>`).join('')}</div><p>${score<70?'Focus next on test coverage, stable waits, and explaining trade-offs.':'Good progress. Review the rubric and add any missing edge cases.'}</p><p class="muted" id="submitRunNote">${icon('info','ic-xs')} Saved in this browser. The score comes from a transparent rubric.</p>`;renderSubmissions();toast('Attempt saved. Your progress was updated.');}
function renderSubmissions(){const root=document.getElementById('submissionList');if(!state.submissions?.length){root.innerHTML=`<div class="empty card"><span class="tile">${icon('inbox')}</span><h3>No submissions yet</h3><p>Open a challenge, write an approach and script, then submit your first attempt.</p><button class="btn btn-primary btn-sm" type="button" data-screen="challenges">${icon('trophy')}Browse challenges</button></div>`;return}root.innerHTML=state.submissions.map(item=>`<article class="submission-item card"><div class="si-head"><span class="submission-score score-pill ${item.score>=70?'good':item.score>=50?'mid':'low'}">${item.score}<small>/100</small></span><div class="si-title"><h3>${escapeHtml(item.title)}</h3><p>${icon('code','ic-xs')} ${escapeHtml(item.framework)} · ${new Date(item.createdAt).toLocaleString()} · Saved locally</p></div><button class="btn btn-secondary btn-sm" type="button" data-retry="${item.challengeId}">${icon('rotate')}Revise this challenge</button></div><div class="si-rubric">${[['Coverage',item.rubric.coverage,30],['Assertions',item.rubric.assertions,25],['Reliability',item.rubric.reliability,25],['Approach',item.rubric.approach,20]].map(([n,v,m])=>`<div><span>${n}</span><b class="tnum">${v}/${m}</b><div class="bar bar-sm"><i style="width:${Math.round(v/m*100)}%"></i></div></div>`).join('')}</div><div class="submission-detail"><p><b>Approach:</b> ${escapeHtml(item.approach||'No approach submitted yet.')}</p><details><summary>${icon('code','ic-sm')}View submitted code <span class="muted">· ${item.run&&item.run.total?`last run ${item.run.passed}/${item.run.total} passed`:'not run before submitting'}</span></summary><pre class="si-code">${escapeHtml(item.code||'No code submitted.')}</pre></details></div></article>`).join('');root.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>beginChallenge(b.dataset.retry)))}
function renderChallengeProgress(){const root=document.getElementById('challengeProgress');if(!root)return;const weak=state.challengeWeak||[];root.innerHTML=`<div class="panel-head"><span class="tile tile-sm" data-tone="gold">${icon('trophy')}</span><div><h3>Hands-on practice progress</h3><p class="sub">${state.submissions?.length||0} submissions · ${weak.length} to revisit</p></div></div>${weak.length?`<div class="weak-list">${weak.map(id=>{const c=challengeData.find(x=>x.id===id);return `<div class="weak"><span>${icon('rotate','ic-sm')}${escapeHtml(c?.title||id)}</span><button class="link-btn" type="button" data-retry="${id}">Revise${icon('arrow-right','ic-sm flip-rtl')}</button></div>`}).join('')}</div>`:`<div class="empty">No challenge submissions yet. <button class="link-btn" type="button" data-screen="challenges">Pick a challenge${icon('arrow-right','ic-sm flip-rtl')}</button></div>`}${(state.submissions||[]).length?`<div class="history-table"><div class="history-row header"><span>Challenge</span><span>Date</span><span>Score</span><span>Framework</span></div>${(state.submissions||[]).slice(0,5).map(x=>`<div class="history-row"><b>${escapeHtml(x.title)}</b><span>${new Date(x.createdAt).toLocaleDateString()}</span><span><span class="score-pill ${x.score>=70?'good':x.score>=50?'mid':'low'}">${x.score}</span></span><span>${escapeHtml(x.framework)}</span></div>`).join('')}</div>`:''}`;root.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>beginChallenge(b.dataset.retry)))}
function renderHistory(){const panel=document.getElementById('historyPanel');if(!state.sessions.length){panel.innerHTML=`<div class="panel-head"><span class="tile tile-sm" data-tone="info">${icon('mic')}</span><div><h3>Interview practice history</h3></div></div><div class="empty">No interview rounds yet. <button class="link-btn" type="button" data-screen="practice">Start a round${icon('arrow-right','ic-sm flip-rtl')}</button></div>`}else panel.innerHTML=`<div class="panel-head"><span class="tile tile-sm" data-tone="info">${icon('mic')}</span><div><h3>Interview practice history</h3><p class="sub">${state.sessions.length} rounds · ${Object.keys(state.scores).length} answers scored · ${Object.keys(state.weak).length} weak topics</p></div></div><div class="history-table"><div class="history-row header"><span>Track</span><span>Date</span><span>Avg score</span><span>Round</span></div>`+state.sessions.map(s=>`<div class="history-row"><b>${trackName(s.track)}</b><span>${s.date}</span><span><span class="score-pill ${s.average>=6?'good':s.average>=4?'mid':'low'}">${s.average}/8</span></span><span>${s.revision?'Revision':'Practice'}</span></div>`).join('')+`</div>`;renderChallengeProgress()}
function handleTargetAction(action){const result=document.getElementById('targetAppResult');if(!result)return;if(action==='peopleops-login'){const u=document.getElementById('practiceTargetUsername')?.value,p=document.getElementById('practiceTargetPassword')?.value;const ok=u==='qa.learner@peopleops.local'&&p==='LabPass123';result.className=`target-result ${ok?'success':'failure'}`;result.textContent=ok?'Signed in · Employee dashboard is available in this simulation.':'Sign-in failed · Check the error state and avoid revealing which field was incorrect.'}else if(action==='api-run'){const endpoint=document.getElementById('embeddedEndpoint').value,method=document.getElementById('embeddedMethod').value,ok=!endpoint.includes('missing');result.className=`target-result ${ok?'success':'failure'}`;result.textContent=JSON.stringify(ok?{status:method==='GET'?200:201,data:{id:'EMP-104',name:'Alex Carter',role:'QA Analyst'}}:{status:404,error:'employee_not_found'},null,2)}else if(action==='cart-run'){result.className='target-result failure';result.textContent='Cart total $48.60 · seeded defect: SAVE10 includes $6.00 shipping; expected merchandise discount $4.80 and total $49.20.'}else if(action==='ui-run'){const q=document.getElementById('embeddedFilter').value.toLowerCase(),rows=['Alex Carter · Quality Engineering','Sam Rivera · Product','Jordan Lee · Quality Engineering'].filter(x=>x.toLowerCase().includes(q));result.className='target-result';result.textContent=rows.length?`Matching rows: ${rows.join(' | ')}`:'No matching employees. Check the empty state and clear-filter recovery.'}else if(action==='mobile-run'){const offline=document.getElementById('embeddedOffline').checked;result.className=`target-result ${offline?'failure':'success'}`;result.textContent=offline?'Offline · Upload remains at 68%; progress should recover after reconnect.':'Online · Upload resumed from 68% and completed once.'}state.labAttempts[activeChallenge.id]=(state.labAttempts[activeChallenge.id]||0)+1;save()}
document.getElementById('challengeTrack').addEventListener('change',renderChallenges);document.getElementById('challengeLevel').addEventListener('change',renderChallenges);document.getElementById('challengeFramework').addEventListener('change',renderChallenges);
document.querySelectorAll('[data-challenge]').forEach(b=>b.addEventListener('click',()=>beginChallenge(b.dataset.challenge)));
document.querySelectorAll('.editor-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.editor-tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.editor-pane').forEach(x=>{const active=x.id===`pane-${b.dataset.editorPane}`;x.hidden=!active;x.classList.toggle('active',active)})}));
document.getElementById('frameworkSelect').addEventListener('change',()=>{document.getElementById('scriptEditor').value=defaultScript(document.getElementById('frameworkSelect').value);saveWorkspaceDraft();toast('Starter template changed for the selected framework.')});
['scriptEditor','approachEditor','testCasesEditor'].forEach(id=>document.getElementById(id).addEventListener('input',()=>saveWorkspaceDraft()));document.getElementById('saveWorkspace').addEventListener('click',()=>saveWorkspaceDraft(true));document.getElementById('submitWorkspace').addEventListener('click',submitWorkspace);
document.getElementById('workspaceHint').addEventListener('click',()=>{const p=document.getElementById('workspaceHintText');p.hidden=!p.hidden});document.getElementById('workspaceModelToggle').addEventListener('click',()=>{const p=document.getElementById('workspaceModel');p.hidden=!p.hidden});document.getElementById('openFullLab').addEventListener('click',()=>{document.querySelectorAll('.lab-tab').forEach(x=>x.classList.toggle('active',x.dataset.lab===activeChallenge.lab));document.querySelectorAll('.lab-panel').forEach(x=>x.classList.toggle('active',x.id===`lab-${activeChallenge.lab}`));showScreen('lab')});
document.addEventListener('click',event=>{const btn=event.target.closest('[data-target-action]');if(btn)handleTargetAction(btn.dataset.targetAction)});
document.getElementById('exportSubmissions').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({submissions:state.submissions||[],drafts:state.workspaceDrafts||[],progress:state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sqa-practice-submissions.json';a.click();URL.revokeObjectURL(a.href)});
document.getElementById('playgroundSubmit').addEventListener('click',()=>{const email=document.getElementById('playgroundEmail').value.trim(),role=document.getElementById('playgroundRole').value,box=document.getElementById('playgroundResult');box.className='result-box';if(!email||!role){box.classList.add('failure');box.innerHTML='<h4>Required fields</h4><p>Enter an email and choose a role.</p>'}else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){box.classList.add('failure');box.innerHTML='<h4>Invalid email format</h4><p>Use a valid address such as name@example.com.</p>'}else{box.classList.add('success');box.innerHTML=`<h4>Request submitted</h4><p>${escapeHtml(role)} request saved in this local simulation.</p>`}state.labAttempts.ui=(state.labAttempts.ui||0)+1;save()});
document.getElementById('playgroundSearch').addEventListener('input',event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('#employeeRows .event').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))});document.getElementById('playgroundAlert').addEventListener('click',()=>{document.getElementById('playgroundNotice').className='result-box success';document.getElementById('playgroundNotice').innerHTML='<h4>Confirmation dialog</h4><p>Simulated alert opened. Check that a user can dismiss it and continue.</p>'});document.getElementById('playgroundReset').addEventListener('click',()=>{document.getElementById('playgroundSearch').value='';document.querySelectorAll('#employeeRows .event').forEach(row=>row.hidden=false);document.getElementById('playgroundNotice').innerHTML='<h4>Reset complete</h4><p>All sample rows are visible again.</p>'});
document.getElementById('bugRecalc').addEventListener('click',()=>{document.getElementById('bugReportResult').className='result-box failure';document.getElementById('bugReportResult').innerHTML='<h4>Defect reproduced</h4><p>Displayed discount $5.40 includes shipping. Expected discount $4.80 on merchandise only.</p>';state.labAttempts.bughunt=(state.labAttempts.bughunt||0)+1;save()});document.getElementById('submitBugReport').addEventListener('click',()=>{const report={title:document.getElementById('bugTitle').value.trim(),steps:document.getElementById('bugSteps').value.trim(),expected:document.getElementById('bugExpected').value.trim(),actual:document.getElementById('bugActual').value.trim(),severity:document.getElementById('bugSeverity').value,createdAt:new Date().toISOString()};const box=document.getElementById('bugReportResult');box.className='result-box';if(!report.title||!report.steps||!report.expected||!report.actual||report.severity==='Choose severity'){box.classList.add('failure');box.innerHTML='<h4>Complete every field</h4><p>A useful report needs a title, steps, expected and actual results, and severity.</p>';return}state.bugReports=state.bugReports||[];state.bugReports.unshift(report);state.labAttempts.bughunt=(state.labAttempts.bughunt||0)+1;save();box.classList.add('success');box.innerHTML=`<h4>Bug report saved</h4><p>${escapeHtml(report.title)} · ${escapeHtml(report.severity)} · Stored in this browser.</p>`});

const DEMO_USERNAME='Admin',DEMO_PASSWORD='admin@123';
const marketingView=document.getElementById('marketing'),loginView=document.getElementById('loginView'),appShell=document.getElementById('appShell');
function openLogin(){marketingView.hidden=true;loginView.hidden=false;appShell.hidden=true;document.getElementById('authError').hidden=true;document.getElementById('authUsername').focus()}
function openApp(){marketingView.hidden=true;loginView.hidden=true;appShell.hidden=false;if(!document.getElementById('targetAppView').childElementCount)beginChallenge(activeChallenge.id,{silent:true});if(window.QA&&QA.enterApp)QA.enterApp();else showScreen('home')}
function openLanding(){marketingView.hidden=false;loginView.hidden=true;appShell.hidden=true;let anchor=null;try{anchor=location.hash.length>1&&!location.hash.startsWith('#/')&&document.getElementById(decodeURIComponent(location.hash.slice(1)))}catch{}if(anchor&&marketingView.contains(anchor))return;try{history.replaceState(null,'',location.pathname+location.search)}catch{}window.scrollTo({top:0,behavior:'auto'})}
document.querySelectorAll('[data-open-login]').forEach(button=>button.addEventListener('click',openLogin));
document.getElementById('backToLanding').addEventListener('click',event=>{event.preventDefault();openLanding()});
document.getElementById('authForm').addEventListener('submit',event=>{event.preventDefault();const username=document.getElementById('authUsername').value.trim(),password=document.getElementById('authPassword').value;if(username!==DEMO_USERNAME||password!==DEMO_PASSWORD){document.getElementById('authError').textContent='That demo login did not match. Check the credentials shown below.';document.getElementById('authError').hidden=false;return}try{localStorage.setItem(AUTH_KEY,JSON.stringify({username:DEMO_USERNAME,signedInAt:new Date().toISOString()}))}catch(error){window.__storageIssue=window.__storageIssue||'blocked';document.getElementById('authError').hidden=true;openApp();toast('This browser is not saving site data. You can practise, but progress will be lost when this tab closes.');return}document.getElementById('authError').hidden=true;openApp()});
document.getElementById('logoutBtn').addEventListener('click',()=>{try{localStorage.removeItem(AUTH_KEY)}catch{}openLanding()});
document.getElementById('copyDemo').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('Username: Admin\nPassword: admin@123');document.getElementById('copyDemo').textContent='Copied'}catch{document.getElementById('authUsername').value=DEMO_USERNAME;document.getElementById('authPassword').value=DEMO_PASSWORD;document.getElementById('authUsername').focus();document.getElementById('copyDemo').textContent='Filled'}});

/* ───────────── Interview prep hub (Qadence) ─────────────
   Shown when no round is open, or when the learner picks "All tracks" during a round
   (the round stays resumable). Any call to renderPractice() switches back to the round. */
var interviewView='session';
(function(){
  const baseRenderPractice=renderPractice;
  renderPractice=function(){interviewView='session';const h=document.getElementById('interviewHub'),sv=document.getElementById('interviewSession');if(h)h.hidden=true;if(sv)sv.hidden=false;return baseRenderPractice.apply(this,arguments)};
  if(!window.QA)return;
  const TRACK_ICON={manual:'list-checks',api:'plug',playwright:'rocket',mobile:'phone'};
  const TRACK_TONE={manual:'',api:'gold',playwright:'violet',mobile:'info'};
  const LEVELS3=['Foundation','Intermediate','Advanced'];
  const pillClass=v=>v>=6?'good':v>=4?'mid':'low';
  function renderHub(){
    const root=document.getElementById('interviewHub'),sv=document.getElementById('interviewSession');if(!root)return;
    if(sv)sv.hidden=true;root.hidden=false;
    const weakIds=Object.keys(state.weak||{}).filter(id=>bank.some(q=>q.id===id));
    const recent=(state.sessions||[]).slice(0,5);
    const resume=session&&Array.isArray(session.questions)&&session.questions.length?`<section class="callout callout-info iv-resume">${icon('mic')}<div><b class="title">Unfinished round · ${escapeHtml(trackName(session.track))}</b>Question ${session.index+1} of ${session.questions.length}${session.revision?' · revision':''}. Your typed answers are saved on this device.<div class="row" style="margin-top:10px"><button class="btn btn-primary btn-sm" type="button" data-resume-interview>${icon('play')}Resume round</button></div></div></section>`:'';
    root.innerHTML=`<div class="page-head legacy-head"><div><span class="eyebrow">${icon('mic','ic-sm')}Interview prep</span><h1>Practise interview answers</h1><p>Answer first, compare with a model answer, then score yourself on a four-part rubric. Every question has a realistic scenario, a hint on request and a Roman Urdu explanation.</p></div><div class="actions"><span class="badge badge-outline">${icon('message')}${bank.length} questions · ${tracks.length} tracks</span></div></div>
${resume}
<ol class="iv-steps" aria-label="How a round works"><li><span>1</span><b>Answer first</b><small>Out loud or typed, 3–6 points</small></li><li><span>2</span><b>Compare</b><small>Model answer and common mistakes</small></li><li><span>3</span><b>Self-score</b><small>Four criteria, 0–2 each</small></li><li><span>4</span><b>Revisit</b><small>Answers under 6/8 join revision</small></li></ol>
<div class="iv-tracks">${tracks.map(t=>{const qs=bank.filter(q=>q.track===t.id),done=qs.filter(q=>state.scores[q.id]!==undefined),avg=done.length?(done.reduce((n,q)=>n+state.scores[q.id],0)/done.length).toFixed(1):null,pct=Math.round(done.length/qs.length*100);return `<article class="card iv-track">
  <div class="iv-track-top"><span class="tile"${TRACK_TONE[t.id]?` data-tone="${TRACK_TONE[t.id]}"`:''}>${icon(TRACK_ICON[t.id]||'mic')}</span><div><h2>${escapeHtml(t.name)}</h2><p>${escapeHtml(t.desc)}</p></div></div>
  <div class="iv-stats"><span><b class="tnum">${qs.length}</b>prompts</span><span><b class="tnum">${done.length}</b>practised</span><span><b class="tnum">${avg??'—'}</b>avg /8</span></div>
  ${barHtml(pct,`${t.name}: ${done.length} of ${qs.length} practised`,'bar-sm')}
  <div class="iv-start"><label class="sr-only" for="ivl-${t.id}">Difficulty for ${escapeHtml(t.name)}</label><select class="select" id="ivl-${t.id}"><option value="all">Mixed difficulty</option>${LEVELS3.map(l=>`<option value="${l}">${l} (${qs.filter(q=>levelFor(q)===l).length})</option>`).join('')}</select><button class="btn btn-primary btn-sm" type="button" data-start-track="${t.id}">${icon('play')}Start round</button></div>
</article>`}).join('')}</div>
<div class="grid g-2 iv-bottom">
  <section class="card" aria-labelledby="ivWeakH"><div class="card-title"><div><h2 id="ivWeakH">${icon('rotate')} Revise weak answers</h2><p class="card-sub">Answers you scored below 6/8</p></div>${weakIds.length?`<button class="btn btn-soft btn-sm" type="button" data-revise-weak>${icon('target')}Revise now</button>`:''}</div>
    ${weakIds.length?`<div class="stack">${weakIds.slice(0,5).map(id=>{const q=bank.find(x=>x.id===id);return `<div class="iv-weak"><span class="score-pill ${pillClass(state.scores[id]??0)}">${state.scores[id]??0}/8</span><span><b>${escapeHtml(q.topic)}</b><small>${escapeHtml(trackName(q.track))}</small></span></div>`}).join('')}</div>`:`<p class="muted">Nothing to revise yet. Answers you score below 6/8 will appear here.</p>`}
  </section>
  <section class="card" aria-labelledby="ivRecentH"><div class="card-title"><div><h2 id="ivRecentH">${icon('clock')} Recent rounds</h2><p class="card-sub">Saved in this browser</p></div><button class="link-btn" type="button" data-screen="progress">${icon('chart','ic-sm')}Progress</button></div>
    ${recent.length?`<div class="stack">${recent.map(r=>`<div class="iv-weak"><span class="score-pill ${pillClass(r.average)}">${r.average}/8</span><span><b>${escapeHtml(trackName(r.track))}</b><small>${escapeHtml(r.date)} · ${r.answered} answered · ${r.revision?'Revision':'Practice'}</small></span></div>`).join('')}</div>`:`<p class="muted">Finish a round to see your scores here.</p>`}
  </section>
</div>`;
    root.querySelectorAll('[data-start-track]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.startTrack,lvl=document.getElementById(`ivl-${id}`)?.value||'all';const f=document.getElementById('difficultyFilter');if(f)f.value=lvl;beginPractice(id,false,lvl);window.scrollTo({top:0,behavior:'auto'})}));
    root.querySelector('[data-resume-interview]')?.addEventListener('click',()=>{renderPractice();window.scrollTo({top:0,behavior:'auto'})});
    root.querySelector('[data-revise-weak]')?.addEventListener('click',()=>{const first=bank.find(q=>state.weak[q.id]);if(first)beginPractice(first.track,true,'all')});
  }
  QA.renderInterviewHub=function(){if(session&&interviewView==='session'){renderPractice();return}renderHub()};
})();

